use clap::{Parser, ValueEnum};
use std::io::{self, Write};
use std::thread;
use std::time::Duration;
use rand::Rng;

mod modules;
use modules::*;

#[derive(Debug, Clone, ValueEnum)]
enum ModuleName {
    #[value(name = "ansible")]
    Ansible,
    #[value(name = "bootlog")]
    Bootlog,
    #[value(name = "botnet")]
    Botnet,
    #[value(name = "bruteforce")]
    Bruteforce,
    #[value(name = "cargo")]
    Cargo,
    #[value(name = "cc")]
    Cc,
    #[value(name = "composer")]
    Composer,
    #[value(name = "cryptomining")]
    Cryptomining,
    #[value(name = "docker_build")]
    DockerBuild,
    #[value(name = "docker_image_rm")]
    DockerImageRm,
    #[value(name = "download")]
    Download,
    #[value(name = "julia")]
    Julia,
    #[value(name = "kernel_compile")]
    KernelCompile,
    #[value(name = "memdump")]
    Memdump,
    #[value(name = "mkinitcpio")]
    Mkinitcpio,
    #[value(name = "rkhunter")]
    Rkhunter,
    #[value(name = "simcity")]
    Simcity,
    #[value(name = "terraform")]
    Terraform,
    #[value(name = "uv")]
    Uv,
    #[value(name = "weblog")]
    Weblog,
    #[value(name = "wpt")]
    Wpt,
}

#[derive(Parser, Debug)]
#[command(name = "genact", version = "1.5.1", about = "A nonsense activity generator", long_about = None)]
struct Args {
    #[arg(short, long)]
    list_modules: bool,

    #[arg(short, long, value_delimiter = ',')]
    modules: Option<Vec<ModuleName>>,

    #[arg(short, long, default_value = "1")]
    speed_factor: f32,

    #[arg(short, long, default_value = "0")]
    instant_print_lines: usize,

    #[arg(long)]
    inhibit: bool,

    #[arg(long)]
    exit_after_time: Option<String>,

    #[arg(long)]
    exit_after_modules: Option<usize>,

    #[arg(long, value_name = "shell")]
    print_completions: Option<String>,

    #[arg(long)]
    print_manpage: bool,
}

fn main() {
    let args = Args::parse();

    if args.list_modules {
        println!("Available modules:");
        println!("  ansible");
        println!("  bootlog");
        println!("  botnet");
        println!("  bruteforce");
        println!("  cargo");
        println!("  cc");
        println!("  composer");
        println!("  cryptomining");
        println!("  docker_build");
        println!("  docker_image_rm");
        println!("  download");
        println!("  julia");
        println!("  kernel_compile");
        println!("  memdump");
        println!("  mkinitcpio");
        println!("  rkhunter");
        println!("  simcity");
        println!("  terraform");
        println!("  uv");
        println!("  weblog");
        println!("  wpt");
        return;
    }

    if let Some(shell) = args.print_completions {
        print_shell_completions(&shell);
        return;
    }

    if args.print_manpage {
        print_manpage();
        return;
    }

    let modules_to_run = if let Some(mods) = args.modules {
        mods
    } else {
        // Default: run random modules
        vec![
            ModuleName::Ansible,
            ModuleName::Bootlog,
            ModuleName::Botnet,
            ModuleName::Bruteforce,
            ModuleName::Cargo,
            ModuleName::Cc,
            ModuleName::Composer,
            ModuleName::Cryptomining,
            ModuleName::DockerBuild,
            ModuleName::DockerImageRm,
            ModuleName::Download,
            ModuleName::Julia,
            ModuleName::KernelCompile,
            ModuleName::Memdump,
            ModuleName::Mkinitcpio,
            ModuleName::Rkhunter,
            ModuleName::Simcity,
            ModuleName::Terraform,
            ModuleName::Uv,
            ModuleName::Weblog,
            ModuleName::Wpt,
        ]
    };

    let mut rng = rand::thread_rng();
    let mut module_count = 0;
    let exit_count = args.exit_after_modules.unwrap_or(std::usize::MAX);

    loop {
        if args.exit_after_modules.is_some() && module_count >= exit_count {
            break;
        }

        let module_idx = rng.gen_range(0..modules_to_run.len());
        let module = &modules_to_run[module_idx];

        run_module(module, args.speed_factor, args.instant_print_lines);
        module_count += 1;

        if args.exit_after_modules.is_some() && module_count >= exit_count {
            break;
        }
    }
}

fn run_module(module: &ModuleName, speed_factor: f32, instant_lines: usize) {
    let delay_ms = (1000.0 / speed_factor) as u64;

    match module {
        ModuleName::Ansible => ansible::run(delay_ms, instant_lines),
        ModuleName::Bootlog => bootlog::run(delay_ms, instant_lines),
        ModuleName::Botnet => botnet::run(delay_ms, instant_lines),
        ModuleName::Bruteforce => bruteforce::run(delay_ms, instant_lines),
        ModuleName::Cargo => cargo::run(delay_ms, instant_lines),
        ModuleName::Cc => cc::run(delay_ms, instant_lines),
        ModuleName::Composer => composer::run(delay_ms, instant_lines),
        ModuleName::Cryptomining => cryptomining::run(delay_ms, instant_lines),
        ModuleName::DockerBuild => docker_build::run(delay_ms, instant_lines),
        ModuleName::DockerImageRm => docker_image_rm::run(delay_ms, instant_lines),
        ModuleName::Download => download::run(delay_ms, instant_lines),
        ModuleName::Julia => julia::run(delay_ms, instant_lines),
        ModuleName::KernelCompile => kernel_compile::run(delay_ms, instant_lines),
        ModuleName::Memdump => memdump::run(delay_ms, instant_lines),
        ModuleName::Mkinitcpio => mkinitcpio::run(delay_ms, instant_lines),
        ModuleName::Rkhunter => rkhunter::run(delay_ms, instant_lines),
        ModuleName::Simcity => simcity::run(delay_ms, instant_lines),
        ModuleName::Terraform => terraform::run(delay_ms, instant_lines),
        ModuleName::Uv => uv::run(delay_ms, instant_lines),
        ModuleName::Weblog => weblog::run(delay_ms, instant_lines),
        ModuleName::Wpt => wpt::run(delay_ms, instant_lines),
    }
}

fn print_shell_completions(shell: &str) {
    match shell {
        "bash" => print_bash_completions(),
        "zsh" => print_zsh_completions(),
        "fish" => print_fish_completions(),
        "elvish" => print_elvish_completions(),
        "powershell" => print_powershell_completions(),
        _ => eprintln!("Unknown shell: {}", shell),
    }
}

fn print_bash_completions() {
    println!(r#"_genact() {{
    local i cur prev opts cmd
    COMPREPLY=()
    if [[ "${{BASH_VERSINFO[0]}}" -ge 4 ]]; then
        cur="$2"
    else
        cur="${{COMP_WORDS[COMP_CWORD]}}"
    fi
    prev="$3"
    cmd=""
    opts=""

    for i in "${{COMP_WORDS[@]:0:COMP_CWORD}}"
    do
        case "${{cmd}},${{i}}" in
            ",$1")
                cmd="genact"
                ;;
            *)
                ;;
        esac
    done

    case "${{cmd}}" in
        genact)
            opts="-l -m -s -i -h -V --list-modules --modules --speed-factor --instant-print-lines --inhibit --exit-after-time --exit-after-modules --print-completions --print-manpage --help --version"
            if [[ ${{cur}} == -* || ${{COMP_CWORD}} -eq 1 ]] ; then
                COMPREPLY=( $(compgen -W "${{opts}}" -- "${{cur}}") )
                return 0
            fi
            case "${{prev}}" in
                --modules|-m)
                    COMPREPLY=( $(compgen -W "ansible bootlog botnet bruteforce cargo cc composer cryptomining docker_build docker_image_rm download julia kernel_compile memdump mkinitcpio rkhunter simcity terraform uv weblog wpt" -- "${{cur}}") )
                    return 0
                    ;;
                --print-completions)
                    COMPREPLY=( $(compgen -W "bash elvish fish powershell zsh" -- "${{cur}}") )
                    return 0
                    ;;
            esac
            ;;
    esac
}} &&
complete -F _genact genact
"#);
}

fn print_zsh_completions() {
    println!("#compdef genact");
}

fn print_fish_completions() {
    println!("complete -c genact -f");
}

fn print_elvish_completions() {
    println!("# Elvish completions for genact");
}

fn print_powershell_completions() {
    println!("# PowerShell completions for genact");
}

fn print_manpage() {
    println!(".ie \\n(.g .ds Aq \\(aq");
    println!(".el .ds Aq '");
    println!(".TH genact 1  \"genact 1.5.1\"");
    println!(".SH NAME");
    println!("genact \\- A nonsense activity generator");
    println!(".SH SYNOPSIS");
    println!("\\fBgenact\\fR [\\fB\\-l\\fR|\\fB\\-\\-list\\-modules\\fR] [\\fB\\-m\\fR|\\fB\\-\\-modules\\fR] [\\fB\\-s\\fR|\\fB\\-\\-speed\\-factor\\fR] [\\fB\\-i\\fR|\\fB\\-\\-instant\\-print\\-lines\\fR] [\\fB\\-\\-inhibit\\fR] [\\fB\\-\\-exit\\-after\\-time\\fR] [\\fB\\-\\-exit\\-after\\-modules\\fR] [\\fB\\-\\-print\\-completions\\fR] [\\fB\\-\\-print\\-manpage\\fR] [\\fB\\-h\\fR|\\fB\\-\\-help\\fR] [\\fB\\-V\\fR|\\fB\\-\\-version\\fR]");
    println!(".SH DESCRIPTION");
    println!("A nonsense activity generator");
    println!(".SH OPTIONS");
    println!(".TP");
    println!("\\fB\\-l\\fR, \\fB\\-\\-list\\-modules\\fR");
    println!("List available modules");
    println!(".TP");
    println!("\\fB\\-m\\fR, \\fB\\-\\-modules\\fR \\fI<MODULES>\\fR");
    println!("Run only these modules");
    println!(".br");
    println!("");
    println!(".br");
    println!("\\fIPossible values:\\fR");
    println!(".RS 14");
    let modules = vec!["ansible", "bootlog", "botnet", "bruteforce", "cargo", "cc",
        "composer", "cryptomining", "docker_build", "docker_image_rm", "download",
        "julia", "kernel_compile", "memdump", "mkinitcpio", "rkhunter", "simcity",
        "terraform", "uv", "weblog", "wpt"];
    for m in modules {
        println!(".IP \\(bu 2");
        println!("{}", m);
    }
    println!(".RE");
}
EOFMAIN
cat /workspace/src/main.rs | head -50

