        print_mem_line(&mut rng);
        thread::sleep(Duration::from_millis(delay_ms));
    }

    println!("Saving work to disk...");
}

fn print_mem_line(rng: &mut rand::rngs::ThreadRng) {
    let addr = format!("{:x}", rng.gen_range(0x700c00000000u64..0x700c50000000u64));
    let hex_chars: String = (0..16)
        .map(|_| format!(" {:02x}", rng.gen_range(0..256)))
        .collect();
    let hex_chars2: String = (0..16)
        .map(|_| format!(" {:02x}", rng.gen_range(0..256)))
        .collect();

    let ascii: String = (0..16)
        .map(|_| {
            let c = rng.gen_range(32..127) as u8 as char;
            if c == '|' { '.' } else { c }
        })
        .collect();

    println!("{}  {}{} |{}|", addr, hex_chars, hex_chars2, ascii);
}
