use rand::Rng;
use std::thread;
use std::time::Duration;

pub fn run(delay_ms: u64, instant_lines: usize) {
    let mut rng = rand::thread_rng();

    let resources = vec![
        "google_memcache_instance.sender",
        "google_pubsub_subscription_iam.steward",
        "google_workstations_workstation_config.signaler",
        "google_compute_node_group.contentor",
        "google_edgecontainer_vpn_connection.comparator",
    ];

    for _ in 0..instant_lines {
        print_terraform_line(&mut rng, &resources);
    }

    for _ in 0..6 {
        print_terraform_line(&mut rng, &resources);
        thread::sleep(Duration::from_millis(delay_ms));
    }

    println!("Saving work to disk...");
}

fn print_terraform_line(rng: &mut rand::rngs::ThreadRng, resources: &[&str]) {
    let resource = resources[rng.gen_range(0..resources.len())];
    let action = ["Creating", "Modifying", "Still modifying", "Still creating"][rng.gen_range(0..4)];
    let elapsed = rng.gen_range(0..10);
    println!("{}: {} ... [id={}, {}s elapsed]", resource, action, resource.split('.').nth(1).unwrap_or(""), elapsed);
}
