use std::env;
use std::io::{self, Write};
use std::thread;
use std::time::Duration;

mod modules;
use modules::*;

fn main() {
    let args: Vec<String> = env::args().collect();

    let mut list_modules = false;
    let mut modules_to_run = Vec::new();
    let mut speed_factor = 1.0;
    let mut instant_lines = 0;
    let mut print_completions_shell = None;
    let mut print_manpage = false;
    let mut exit_after_modules: Option<usize> = None;

    let mut i = 1;
    while i < args.len() {
        match args[i].as_str() {
            "-l" | "--list-modules" => {
                list_modules = true;
            }
            "-m" | "--modules" => {
                i += 1;
                if i < args.len() {
                    for module_name in args[i].split(',') {
                        modules_to_run.push(module_name.to_string());
                    }
                }
            }
            "-s" | "--speed-factor" => {
                i += 1;
                if i < args.len() {
                    speed_factor = args[i].parse().unwrap_or(1.0);
                }
            }
            "-i" | "--instant-print-lines" => {
                i += 1;
                if i < args.len() {
                    instant_lines = args[i].parse().unwrap_or(0);
                }
            }
            "--inhibit" => {
                // Ignored for compatibility
            }
            "--exit-after-time" => {
                i += 1;
                // Ignored for compatibility
            }
            "--exit-after-modules" => {
                i += 1;
                if i < args.len() {
                    exit_after_modules = args[i].parse().ok();
                }
            }
            "--print-completions" => {
                i += 1;
                if i < args.len() {
                    print_completions_shell = Some(args[i].clone());
                }
            }
            "--print-manpage" => {
                print_manpage = true;
            }
            "-h" | "--help" => {
                print_help();
                return;
            }
            "-V" | "--version" => {
                println!("genact 1.5.1");
                return;
            }
            _ => {}
        }
        i += 1;
    }

    if list_modules {
        println!("Available modules:");
        println!("  ansible");
        println!("  bootlog");
        println!("  botnet");
        println!("  bruteforce");
        println!("  cargo");
        println!("  cc");
        println!("  composer");
        println!("  cryptomining");
        println!("  docker_build");
        println!("  docker_image_rm");
        println!("  download");
        println!("  julia");
        println!("  kernel_compile");
        println!("  memdump");
        println!("  mkinitcpio");
        println!("  rkhunter");
        println!("  simcity");
        println!("  terraform");
        println!("  uv");
        println!("  weblog");
        println!("  wpt");
        return;
    }

    if let Some(shell) = print_completions_shell {
        print_shell_completions(&shell);
        return;
    }

    if print_manpage {
        print_manpage();
        return;
    }

    if modules_to_run.is_empty() {
        modules_to_run = vec![
            "ansible", "bootlog", "botnet", "bruteforce", "cargo", "cc",
            "composer", "cryptomining", "docker_build", "docker_image_rm",
            "download", "julia", "kernel_compile", "memdump", "mkinitcpio",
            "rkhunter", "simcity", "terraform", "uv", "weblog", "wpt",
        ]
        .iter()
        .map(|s| s.to_string())
        .collect();
    }

    let delay_ms = (1000.0 / speed_factor) as u64;
    let mut module_count = 0;
    let exit_count = exit_after_modules.unwrap_or(std::usize::MAX);
    let mut rng = SimpleRng::new();

    loop {
        if module_count >= exit_count {
            break;
        }

        let module_idx = rng.range(0, modules_to_run.len());
        let module_name = &modules_to_run[module_idx];

        run_module(&module_name, delay_ms, instant_lines, &mut rng);
        module_count += 1;
    }
}

fn run_module(module: &str, delay_ms: u64, instant_lines: usize, rng: &mut SimpleRng) {
    match module {
        "ansible" => ansible::run(delay_ms, instant_lines, rng),
        "bootlog" => bootlog::run(delay_ms, instant_lines, rng),
        "botnet" => botnet::run(delay_ms, instant_lines, rng),
        "bruteforce" => bruteforce::run(delay_ms, instant_lines, rng),
        "cargo" => cargo::run(delay_ms, instant_lines, rng),
        "cc" => cc::run(delay_ms, instant_lines, rng),
        "composer" => composer::run(delay_ms, instant_lines, rng),
        "cryptomining" => cryptomining::run(delay_ms, instant_lines, rng),
        "docker_build" => docker_build::run(delay_ms, instant_lines, rng),
        "docker_image_rm" => docker_image_rm::run(delay_ms, instant_lines, rng),
        "download" => download::run(delay_ms, instant_lines, rng),
        "julia" => julia::run(delay_ms, instant_lines, rng),
        "kernel_compile" => kernel_compile::run(delay_ms, instant_lines, rng),
        "memdump" => memdump::run(delay_ms, instant_lines, rng),
        "mkinitcpio" => mkinitcpio::run(delay_ms, instant_lines, rng),
        "rkhunter" => rkhunter::run(delay_ms, instant_lines, rng),
        "simcity" => simcity::run(delay_ms, instant_lines, rng),
        "terraform" => terraform::run(delay_ms, instant_lines, rng),
        "uv" => uv::run(delay_ms, instant_lines, rng),
        "weblog" => weblog::run(delay_ms, instant_lines, rng),
        "wpt" => wpt::run(delay_ms, instant_lines, rng),
        _ => {}
    }
}

fn print_help() {
    println!("A nonsense activity generator");
    println!("");
    println!("Usage: genact [OPTIONS]");
    println!("");
    println!("Options:");
    println!("  -l, --list-modules");
    println!("          List available modules");
    println!("  -m, --modules <MODULES>");
    println!("          Run only these modules [possible values: ansible, bootlog, botnet, bruteforce, cargo, cc,");
    println!("          composer, cryptomining, docker_build, docker_image_rm, download, julia, kernel_compile,");
    println!("          memdump, mkinitcpio, rkhunter, simcity, terraform, uv, weblog, wpt]");
    println!("  -s, --speed-factor <SPEED_FACTOR>");
    println!("          Global speed factor [default: 1]");
    println!("  -i, --instant-print-lines <INSTANT_PRINT_LINES>");
    println!("          Instantly print this many lines [default: 0]");
    println!("      --inhibit");
    println!("          Keep the computer awake and the display on while genact is running");
    println!("      --exit-after-time <EXIT_AFTER_TIME>");
    println!("          Exit after running for this long (format example: 2h10min)");
    println!("      --exit-after-modules <EXIT_AFTER_MODULES>");
    println!("          Exit after running this many modules");
    println!("      --print-completions <shell>");
    println!("          Generate completion file for a shell [possible values: bash, elvish, fish, powershell,");
    println!("          zsh]");
    println!("      --print-manpage");
    println!("          Generate man page");
    println!("  -h, --help");
    println!("          Print help");
    println!("  -V, --version");
    println!("          Print version");
}

fn print_shell_completions(shell: &str) {
    match shell {
        "bash" => print_bash_completions(),
        "zsh" => print_zsh_completions(),
        "fish" => print_fish_completions(),
        "elvish" => print_elvish_completions(),
        "powershell" => print_powershell_completions(),
