use std::time::Duration;

static CRATES: &[&str] = &[
    "aio", "hex_literals", "picotcp-sys", "tupm", "base32", "shmem", "unreachable",
    "clockwork", "bmp", "libloadorder-ffi", "line_intersection", "edit-distance",
    "allegro_dialog-sys", "pcb-llvm", "hello-cli", "hyper-staticfile", "cargo-crusader",
    "tokio", "serde", "anyhow", "rand", "num-derive", "rustfmt-nightly",
];

pub fn run(delay_ms: u64, instant_lines: usize, rng: &mut SimpleRng) {
    for _ in 0..instant_lines {
        let crate_name = CRATES[rng.range(0, CRATES.len())];
        let version = format!("v{}.{}.{}", rng.range(0, 10), rng.range(0, 30), rng.range(0, 50));
        println!("\x1b[1;32m Downloading\x1b[0m {} {}", crate_name, version);
    }

    for _ in 0..20 {
        let crate_name = CRATES[rng.range(0, CRATES.len())];
        let version = format!("v{}.{}.{}", rng.range(0, 10), rng.range(0, 30), rng.range(0, 50));
        println!("\x1b[1;32m Downloading\x1b[0m {} {}", crate_name, version);
        thread::sleep(Duration::from_millis(delay_ms));
    }

    println!("Saving work to disk...");
    thread::sleep(Duration::from_millis(delay_ms * 2));
}
EOF

