use crate::SimpleRng;
use std::thread;
use std::time::Duration;

pub fn run(delay_ms: u64, instant_lines: usize, rng: &mut SimpleRng) {
    for _ in 0..instant_lines {
        print_mem_line(rng);
    }

    for _ in 0..10 {
        print_mem_line(rng);
        thread::sleep(Duration::from_millis(delay_ms));
    }

    println!("Saving work to disk...");
}

fn print_mem_line(rng: &mut crate::SimpleRng) {
    let addr = format!("{:x}", rng.range(0x700c0000 as usize, 0x700c5000 as usize));
    let hex_chars: String = (0..16)
        .map(|_| format!(" {:02x}", rng.range(0, 256)))
        .collect();
    let hex_chars2: String = (0..16)
        .map(|_| format!(" {:02x}", rng.range(0, 256)))
        .collect();

    let ascii: String = (0..16)
        .map(|_| {
            let c = rng.range(32, 127) as u8 as char;
            if c == '|' { '.' } else { c }
        })
        .collect();

    println!("{}  {}{} |{}|", addr, hex_chars, hex_chars2, ascii);
}
EOF

